insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_lingaraj','Lingaraj Temple','Odisha','Khordha','Heritage','Lingaraj Temple represents the pinnacle of Kalinga architectural style. Built by Somavamsi king Jajati Keshari in the 11th century, the main Deula towers at 180 feet. Surrounding Bindusagar Tank, the temple complex houses over 50 smaller shrines.','20.2382','85.8338','needs_review','October – March','1',array['temple','heritage','spiritual','architecture','day trip','low cost escape']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
