insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_konark','Konark Sun Temple (UNESCO)','Odisha','Puri','Heritage','Built in 1250 AD by King Narasimhadeva I of the Eastern Ganga dynasty, the ''Black Pagoda'' is designed as a gargantuan chariot for Sun God Surya, drawn by 7 galloping stone horses. Its 24 carved stone wheels function as accurate sundials measuring time to the exact minute. Highlights include erotic sculptures, celestial musicians, and the Natya Mandap dancing hall.','19.8876','86.0945','needs_review','October – March','1',array['unesco','heritage','architecture','sun temple','history','photography','must see']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
