insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_ramachandi','Ramachandi Temple & Beach','Odisha','Puri','Beach','Located 7 km from Konark on the Puri Marine Drive, Ramachandi is situated at the picturesque confluence of Kushabhadra River and Bay of Bengal. Named after presiding deity Goddess Ramachandi, the calm river mouth waters host water sports, jet skiing, speedboating, and serene lotus ponds.','19.8611','86.0583','needs_review','October – March','1',array['beach','river mouth','water sports','boating','temple','picnic']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
