insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_alarnath','Alarnath Temple Brahmagiri','Odisha','Puri','Temple','Alarnath Temple in Brahmagiri holds supreme spiritual importance. During the 15-day ''Anavasara'' period after Snana Yatra when Lord Jagannath is unavailable for darshan, it is believed Lord Jagannath manifests as Alarnath (four-armed Vishnu) here. Associated with Sri Chaitanya Mahaprabhu who meditated on a stone slab that melted under his devotion.','19.8','85.65','needs_review','Year-round (Special in June/July Anavasara)','1',array['temple','spiritual','chaitanya','heritage','day trip']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_sakhigopal','Sakhigopal Temple','Odisha','Puri','Temple','Sakhigopal (''Witness Gopal'') Temple at Satyabadi is tied to the legend of Lord Krishna traveling from Vrindavan to Odisha to testify as witness for a young devotee. Pilgrims visiting Puri Jagannath traditionally complete their pilgrimage with darshan at Sakhigopal. Famous for its Anla Navami festival when Radha''s feet are visible.','19.95','85.8333','needs_review','October – March','1',array['temple','spiritual','krishna','heritage','low cost escape']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_ansupa','Ansupa Freshwater Lake & Saranda Hill','Odisha','Cuttack','Lake','Ansupa is a picturesque 140-hectare horseshoe freshwater lake formed by the Mahanadi river meander. Flanked by Saranda and Bishnupur hills in Banki sub-division, it welcomes thousands of migratory birds in winter. Features bamboo eco-cottages, boating, tree-top walks, and ancient fort ruins atop Saranda hill.','20.4583','85.6','needs_review','November – February','1',array['lake','freshwater','boating','migratory birds','hill','picnic','day trip']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
