insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_naraj_maragath','Naraj Mahanadi Barrage & Peacock Valley','Odisha','Cuttack','River','Naraj is the scenic vantage point where the mighty Mahanadi River splits into its main deltaic branch, the Kathajodi River. Featuring a sprawling barrage, ancient Buddhist rock carvings at Siddheswar hill, and the famous Siddheswar Peacock Valley sanctuary where dozens of wild peacocks feed daily.','20.4667','85.7667','needs_review','Year-round (Best at 4 PM for peacock feeding)','1',array['river','barrage','peacocks','sunset spot','road trip','low cost escape','photography']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_charchika','Charchika Temple Banki','Odisha','Cuttack','Temple','Maa Charchika Temple in Banki town is one of Odisha''s oldest Shakti shrines, dedicated to eight-armed Goddess Chamunda (Charchika). Perched on the small Ruchika hill on the banks of Renuka River (tributary of Mahanadi), it draws huge crowds during Durga Puja.','20.3833','85.5333','needs_review','October – March (Durga Puja in Oct)','1',array['temple','shakti peetha','river','heritage','day trip','low cost escape']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_bhattarika','Bhattarika Temple & Mahanadi Gorge','Odisha','Cuttack','Temple','Bhattarika Temple is dramatically situated on the rocky bank of the Mahanadi River at Badamba. Dedicated to Goddess Bhattarika (form of Shakti), mythology holds that Lord Parashurama prayed here to regain his celestial power. The temple offers magnificent river gorge vistas.','20.4167','85.3333','needs_review','October – March','1',array['temple','river','gorge','nature','peaceful','day trip','hidden gem']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_netaji_museum','Netaji Birthplace Museum Cuttack','Odisha','Cuttack','Heritage','Netaji Birthplace Museum is housed in ''Janakinath Bhawan'' in Oriya Bazaar, Cuttack—the ancestral home where legendary freedom fighter Netaji Subhas Chandra Bose was born on January 23, 1897. Preserved in authentic period style, 12 galleries display his letters, uniforms, photographs, and personal artifacts.','20.475','85.875','needs_review','Year-round','1',array['museum','history','freedom movement','subhas chandra bose','cuttack','low cost escape']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
