insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_rushikulya','Rushikulya Olive Ridley Turtle Rookery','Odisha','Ganjam','Wildlife','Rushikulya river mouth beach is one of the world''s premier mass nesting sites for Olive Ridley sea turtles (Lepidochelys olivacea). Every year between February and March, the phenomenon of ''Arribada'' occurs as over 300,000 to 500,000 female sea turtles emerge simultaneously under night skies to lay millions of eggs.','19.3833','85.0667','needs_review','February – May (Nesting Feb/Mar, Hatching Apr/May)','1',array['turtles','olive ridley','arribada','beach','wildlife','conservation','nature']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_simlipal','Simlipal National Park & Tiger Reserve','Odisha','Mayurbhanj','Wildlife','Simlipal is Odisha''s flagship wilderness—a UNESCO World Network Biosphere Reserve spanning 2,750 sq km of dense sal forests, rolling plateaus, and 1,076 species of plants. Home to the world''s only wild melanistic (black) tigers, Bengal tigers, 500+ elephants, leopards, and thunderous waterfalls Barehipani and Joranda.','21.9333','86.35','needs_review','November – June (Park closed July–October for monsoon)','3',array['national park','tiger reserve','waterfall','wildlife','safari','forest','unesco biosphere']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
