insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_bhitarkanika','Bhitarkanika National Park & Crocodile Safari','Odisha','Kendrapara','Wildlife','Bhitarkanika is India''s second largest mangrove ecosystem (672 sq km) and a protected Ramsar Wetland. Famous for harboring the world''s largest population of giant Saltwater Crocodiles (including 20-foot Guinness record holders), spotted deer, king cobras, and 215 species of birds. Exploration is done entirely via quiet motorboat river safaris through thick mangrove creeks.','20.7','86.8667','needs_review','October – March (Closed May 15 – July 31 for crocodile breeding)','2',array['national park','mangrove','crocodiles','boat safari','ramsar site','wildlife','must see']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
