insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_ratnagiri','Ratnagiri & Udayagiri Buddhist Monasteries','Odisha','Jajpur','Heritage','Part of Odisha''s famed ''Diamond Triangle'' of Buddhist heritage, Ratnagiri was a rival to Nalanda as a major university of Mahayana and Tantric Buddhism. Features exquisite green chlorite carved monastic doorways, large seated Buddha statues, a massive brick stupa, and thousands of votive stupas.','20.6417','86.3333','needs_review','October – March','1',array['buddhism','archaeology','monastery','unesco candidate','heritage','history','day trip']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_kapilash','Kapilash Temple & Deer Park','Odisha','Dhenkanal','Mountain','Perched at 457 meters (1,500 feet) on Kapilash hill in Dhenkanal, Lord Chandrasekhar Temple was built in 1246 AD by King Narasimhadeva I. Reached via a winding 12-km ghat road or 1,352 stone steps, the hilltop sanctuary is surrounded by dense forest, a deer park, and historic caves.','20.6833','85.7667','needs_review','October – March (Maha Shivratri in Feb/Mar)','1',array['hill','temple','shiva','forest','viewpoint','day trip']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
