insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_siali_beach','Siali Sea Beach','Odisha','Jagatsinghpur','Beach','Siali Beach is one of Odisha''s finest secluded secrets. Far from tourist crowds, this pristine stretch of shoreline features soft golden sands framed by dense casuarina forests and gentle waves. At low tide, the beach transforms into a crimson canvas dotted with thousands of ghost crabs.','20.0833','86.5833','needs_review','October – March','1',array['beach','untouched','casuarina','solitude','red crabs','hidden gem']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_kantilo_nilamadhaba','Kantilo Nilamadhaba Temple','Odisha','Nayagarh','Heritage','Perched atop the twin Brahmadri hills overlooking the mighty Mahanadi river, Kantilo Nilamadhaba is one of the most historically momentous temples of Odisha. According to scripture, it was here that the Sabara tribal chieftain Viswavasu secretly worshipped the sapphire deity Nilamadhaba before Lord Jagannath took wood manifestation at Puri.','20.3547','85.1878','needs_review','October – March','1',array['jagannath root','temple','brahmagiri hill','mahanadi river','bell metal','heritage']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
