insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_nrusinghanath','Nrusinghanath Temple & Waterfall','Odisha','Bargarh','Waterfall','Nrusinghanath is situated on the northern slope of the legendary Gandhamardan mountain (believed to be the hill brought by Lord Hanuman with the Sanjeevani herb). Built in 1360 AD by King Baijal Singh Dev, the temple honors Lord Marjara Keshari (feline-faced avatar of Vishnu). Above the temple, the perennial spring streams down creating sacred waterfalls like Kapil Dhar, Bhim Dhar, and Chal Dhar.','20.9','82.8333','needs_review','October – March','2',array['waterfall','temple','gandhamardan hills','ayurveda','medicinal plants','14th century']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
