insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_sureswari','Sureswari Temple & Mahanadi Confluence','Odisha','Subarnapur','Heritage','Sonepur, known as the ''Second Varanasi of India'', is crowned by the Maa Sureswari Temple built by King Subarnakeshari in the 10th century. Overlooking the grand sangam (confluence) where the river Tel merges into the Mahanadi, the shrine is a celebrated center of Tantric and Shakta veneration.','20.84','83.92','needs_review','October – March','1',array['shakti','temple','mahanadi','tel river','confluence','tantra','sonepur']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_subarnameru','Subarnameru Temple & Silk Weavers Village','Odisha','Subarnapur','Heritage','Subarnameru Temple on the banks of river Tel is dedicated to Lord Shiva. Local lore recounts that gold coins once showered upon this shrine, giving the town its name ''Subarnapur'' (City of Gold). Adjacent weaving clusters produce the GI-tagged Sonepuri and Bomkai silk sarees with intricate double-ikat motifs.','20.835','83.915','needs_review','October – March','1',array['temple','shiva','silk','handloom','bomkai','craft','heritage']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_koili_ghoghar','Koili Ghoghar Waterfall & Cave Temple','Odisha','Jharsuguda','Waterfall','Koili Ghoghar is nestled in the dense reserve forests of Lakhanpur in Jharsuguda district. The rivulets of the ''Ahiraj'' nallah cascade down stepped rock tiers from a height of 200 feet into a tranquil natural gorge. Inside a rock cave beneath the stream sits a submerged, perennially wet Shiva Lingam known as Maheshwarnath.','21.6833','83.5667','needs_review','October – March','1',array['waterfall','cave temple','submerged lingam','sal forest','stream','nature']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_bikramkhol','Bikramkhol Prehistoric Rock Art & Cave','Odisha','Jharsuguda','Heritage','Hidden in the reserve forests of Belpahar, Bikramkhol is one of the world''s most debated epigraphic discoveries. Discovered in the 1930s by K.P. Jayaswal, the 37-meter sandstone rock shelter contains geometric and pictographic characters carved and painted into the rock face, dated between 3000 BC and 1500 BC.','21.7833','83.6167','needs_review','October – March','1',array['rock art','prehistoric','pictographic','bronze age','caves','ancient script']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_patora_dam','Patora Dam & Yogiswar Temple','Odisha','Nuapada','Lake','Built across the Jonk river, Patora Dam (officially Upper Jonk Irrigation Project) is set amid dramatic cliff formations and serene waters. Adjacent to the reservoir, the modern Yogiswar temple features a grand Shiva statue and manicured hillside gardens.','20.7333','82.55','needs_review','October – March','1',array['dam','reservoir','lake','shiva','hills','picnic','boating']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_sunabeda_sanctuary','Sunabeda Wildlife Sanctuary & Canyon','Odisha','Nuapada','Wildlife','Sunabeda Wildlife Sanctuary is an extraordinary ecological wonderland covering 600 sq km across a high plateau carved with dramatic canyons, gorges, and 11 waterfalls including Beniadhara and Kharaldhara. Formed in dry deciduous forest, it serves as an important catchment for the Jonk river.','20.6','82.4667','needs_review','November – April','2',array['tiger reserve','canyon','waterfalls','plateau','barasingha','wilderness']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_boudh_star_temples','Star-Shaped Temples of Boudh','Odisha','Boudh','Heritage','The three temples of Rameswar, Jogiswar, and Paschimeswar in Boudh town are an architectural wonder of medieval India. Constructed in the 9th century AD under the Bhanja rulers, each temple''s sanctum sits upon an eight-pointed star platform with intricately sculpted Shaivite devatas in red sandstone.','20.84','84.32','needs_review','October – March','1',array['star-shaped','9th century','bhanja dynasty','unique architecture','shiva','heritage']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_boudh_buddha','Giant Seated Buddha of Boudh','Odisha','Boudh','Heritage','Boudh was historically a major center of Vajrayana and Tantric Buddhism in ancient Odra desa. In the heart of the town sits a colossal 7-foot high black stone statue of Lord Buddha seated in Bhumisparsha mudra on a lotus throne, flanked by Gandharvas and celestial apsaras.','20.835','84.325','needs_review','October – March','1',array['buddhism','9th century','bhumisparsha','monolith','heritage','peaceful']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_pradhanpat','Pradhanpat Waterfall & Basanta Nivas','Odisha','Deogarh','Waterfall','Pradhanpat is a mesmerizing waterfall situated less than 1 km from the historic royal town of Deogarh. Cascading from the Pradhanpat hill into crystalline pools, the waterfall is bordered by the heritage Basanta Nivas and Lalit Basanta royal summer palaces built by King Sir Basudeb Sudhal Deb in the late 19th century.','21.5333','84.7333','needs_review','October – March','1',array['waterfall','palace','hydro power history','nature','scenic','heritage']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_kurudkut','Kurudkut Hydro Falls & Forest Valley','Odisha','Deogarh','Nature','Kurudkut is an enchanting jungle cascade located 15 km from Deogarh town. Famous as the original mountain source used by Raja Sir Basudeb Sudhal Deb to pioneer hydro-electricity in the former princely state of Bamra in the 1890s, it offers serene nature trails and lush forest picnics.','21.5833','84.8167','needs_review','October – March','1',array['waterfall','forest','valley','trekking','solitude','green']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_devkund','Devkund Sacred Waterfalls & Kundas','Odisha','Mayurbhanj','Waterfall','Devkund (''Bathtub of the Gods'') is situated in the outer buffer zone of Simlipal Biosphere Reserve. Flowing from the hills of Udala, the mountain river creates five successive natural pools (Kundas), the deepest being Devkund, overlooked by the revered temple of Goddess Ambika on a high rock cliff.','21.6833','86.4833','needs_review','November – March','1',array['waterfall','5 natural pools','simlipal buffer','goddess ambika','forest trek','nature']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
