insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_khandadhar_keonjhar','Khandadhar Waterfall (Keonjhar)','Odisha','Keonjhar','Waterfall','Set amidst dense sal and mixed deciduous forests in Keonjhar district, this 152-meter (500 ft) waterfall cascades down vertical cliff faces. Fed by perennial hill streams, it creates shimmering plumes of spray that mist the surrounding valley.','21.5','85.35','needs_review','October – March','1',array['waterfall','keonjhar','mist','hills','dense forest','trekking']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags;
